mapper.select:
/* 검진기록 첨부 목록 조회(최신순) */ SELECT
FROM CKUP_RCD_ATCH A JOIN ATCH_FILE F ON F.ATCH_FILE_SN = A.ATCH_FILE_SN LEFT JOIN COM_CD T ON T.COM_CD = A.ATCH_TYPE_CD AND T.COM_CD_PRNT_SN IS NOT NULL LEFT JOIN COM_CD K ON K.COM_CD = A.IMG_KND_CD AND K.COM_CD_PRNT_SN IS NOT NULL LEFT JOIN COM_CD R ON R.COM_CD = A.SHT_REGN_CD AND R.COM_CD_PRNT_SN IS NOT NULL WHERE A.CKUP_RCD_SN = #{cond.ckupRcdSn} AND A.DEL_YN = 'N'
AND A.ATCH_TYPE_CD = #{cond.atchTypeCd}
ORDER BY A.REG_DT DESC , A.CKUP_RCD_ATCH_SN DESC

/* 검진기록들의 첨부 목록 조회(최신순) */ SELECT
FROM CKUP_RCD_ATCH A JOIN ATCH_FILE F ON F.ATCH_FILE_SN = A.ATCH_FILE_SN LEFT JOIN COM_CD T ON T.COM_CD = A.ATCH_TYPE_CD AND T.COM_CD_PRNT_SN IS NOT NULL LEFT JOIN COM_CD K ON K.COM_CD = A.IMG_KND_CD AND K.COM_CD_PRNT_SN IS NOT NULL LEFT JOIN COM_CD R ON R.COM_CD = A.SHT_REGN_CD AND R.COM_CD_PRNT_SN IS NOT NULL WHERE A.CKUP_RCD_SN IN #{sn} AND A.DEL_YN = 'N'
AND A.ATCH_TYPE_CD = #{cond.atchTypeCd}
ORDER BY A.REG_DT DESC , A.CKUP_RCD_ATCH_SN DESC

mapper.insert:
/* 검진기록 첨부 등록 */
INSERT INTO CKUP_RCD_ATCH
     ( CKUP_RCD_SN
     , ATCH_FILE_SN
     , ATCH_TYPE_CD
     , IMG_KND_CD
     , SHT_REGN_CD
     , DEL_YN
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{ckupRcdSn}
     , #{atchFileSn}
     , #{atchTypeCd}
     , #{imgKndCd}
     , #{shtRegnCd}
     , 'N'
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

mapper.update:
/* 검진기록 첨부 수정(파일 교체·유형) */
UPDATE CKUP_RCD_ATCH
   SET ATCH_FILE_SN = #{attachment.atchFileSn}
     , ATCH_TYPE_CD = #{attachment.atchTypeCd}
     , IMG_KND_CD   = #{attachment.imgKndCd}
     , SHT_REGN_CD  = #{attachment.shtRegnCd}
     , MDFR_ID      = #{actorId}
     , MDFCN_DT     = NOW()
 WHERE CKUP_RCD_ATCH_SN = #{attachment.ckupRcdAtchSn}
   AND DEL_YN = 'N'

/* 검진기록 첨부 삭제 */
UPDATE CKUP_RCD_ATCH
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE CKUP_RCD_ATCH_SN = #{ckupRcdAtchSn}
   AND DEL_YN = 'N'
